CREATE TYPE public.app_role AS ENUM ('admin','moderator','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_self_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE TABLE public.partner_requests (user_id uuid PRIMARY KEY REFERENCES public.profiles(user_id), full_name text NOT NULL, tax_id text NOT NULL, crc_number text NOT NULL, pix_type text NOT NULL CHECK(pix_type IN ('cpf','cnpj','email','phone','random')), pix_key text NOT NULL, status text NOT NULL DEFAULT 'pending_approval' CHECK(status IN ('pending_approval','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.partner_requests TO authenticated;
GRANT ALL ON public.partner_requests TO service_role;
ALTER TABLE public.partner_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY partner_read ON public.partner_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY partner_submit ON public.partner_requests FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='pending_approval');
CREATE POLICY partner_review ON public.partner_requests FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.coupons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,partner_id uuid NOT NULL REFERENCES public.partner_requests(user_id),discount_percent integer NOT NULL DEFAULT 10 CHECK(discount_percent BETWEEN 0 AND 100),commission_percent integer NOT NULL DEFAULT 20 CHECK(commission_percent BETWEEN 0 AND 100),is_active boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(partner_id));
GRANT SELECT,INSERT,UPDATE ON public.coupons TO authenticated;
GRANT ALL ON public.coupons TO service_role;
ALTER TABLE public.coupons ENABLE ROW LEVEL SECURITY;
CREATE POLICY coupon_read ON public.coupons FOR SELECT TO authenticated USING(partner_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY coupon_admin_insert ON public.coupons FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY coupon_admin_update ON public.coupons FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.commissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),partner_id uuid NOT NULL REFERENCES public.partner_requests(user_id),subscription_id uuid,client_name text,amount_cents bigint NOT NULL DEFAULT 0 CHECK(amount_cents>=0),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','available','paid')),created_at timestamptz NOT NULL DEFAULT now(),paid_at timestamptz,receipt_url text);
GRANT SELECT,UPDATE ON public.commissions TO authenticated;
GRANT ALL ON public.commissions TO service_role;
ALTER TABLE public.commissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY commission_read ON public.commissions FOR SELECT TO authenticated USING(partner_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY commission_admin_update ON public.commissions FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.accountant_invites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_user_id uuid NOT NULL REFERENCES public.profiles(user_id),accountant_email text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.accountant_invites TO authenticated;
GRANT ALL ON public.accountant_invites TO service_role;
ALTER TABLE public.accountant_invites ENABLE ROW LEVEL SECURITY;
CREATE POLICY invite_owner_read ON public.accountant_invites FOR SELECT TO authenticated USING(owner_user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY invite_owner_insert ON public.accountant_invites FOR INSERT TO authenticated WITH CHECK(owner_user_id=auth.uid() AND status='pending');